import org.junit.*;import org.junit.rules.*;import org.junit.runner.*;import org.junit.runners.MethodSorters;import static org.junit.Assert.*;import org.openqa.selenium.*;import org.openqa.selenium.chrome.*;import org.openqa.selenium.support.ui.*;import java.time.Duration;import java.nio.file.*;import java.util.*;
@FixMethodOrder(MethodSorters.NAME_ASCENDING)
public class SeleniumFlowTest {
 static WebDriver d;static WebDriverWait wait;static Path out=Paths.get("verification/results/selenium");
 @BeforeClass public static void start()throws Exception{Files.createDirectories(out);System.setProperty("webdriver.chrome.driver",Paths.get("verification/tools/chromedriver-win64/chromedriver.exe").toAbsolutePath().toString());ChromeOptions o=new ChromeOptions();o.setBinary("C:/Program Files/Google/Chrome/Application/chrome.exe");o.addArguments("--headless=new","--window-size=1440,1050","--no-first-run");Map<String,Object> prefs=new HashMap<>();prefs.put("download.default_directory",out.toAbsolutePath().toString());prefs.put("download.prompt_for_download",false);o.setExperimentalOption("prefs",prefs);d=new ChromeDriver(o);wait=new WebDriverWait(d,Duration.ofSeconds(20));FullFunctionalTest.setup();}
 @AfterClass public static void stop()throws Exception{if(d!=null)d.quit();FullFunctionalTest.close();}
 @Before public void login(){d.manage().deleteAllCookies();d.get(FullFunctionalTest.base+"/login");type(By.name("username"),"testadmin");type(By.name("password"),"Test2026ok");d.findElement(By.id("btnSubmit")).click();wait.until(x->x.getCurrentUrl().contains("/index"));}
 @Rule public TestWatcher evidence=new TestWatcher(){protected void finished(Description desc){try{Files.write(out.resolve(desc.getMethodName()+".png"),((TakesScreenshot)d).getScreenshotAs(OutputType.BYTES));Files.write(out.resolve(desc.getMethodName()+".html"),d.getPageSource().getBytes("UTF-8"));}catch(Exception e){System.err.println(e);}}};
 static void type(By by,String s){WebElement e=wait.until(ExpectedConditions.visibilityOfElementLocated(by));e.clear();e.sendKeys(s);}static Object js(String s,Object...a){return ((JavascriptExecutor)d).executeScript(s,a);}static void page(String path){d.get(FullFunctionalTest.base+path);wait.until(x->"complete".equals(js("return document.readyState")));wait.until(x->Boolean.TRUE.equals(js("return !window.jQuery || jQuery.active===0")));try{Thread.sleep(700);}catch(Exception e){}assertFalse(d.findElement(By.tagName("body")).getText().contains("服务器错误"));}static void confirmLayer(){wait.until(ExpectedConditions.elementToBeClickable(By.cssSelector(".layui-layer-btn0"))).click();}
 @Test public void a_loginAndUnifiedEntry(){assertTrue(d.findElement(By.tagName("body")).getText().contains("测试管理员"));assertTrue(d.findElements(By.cssSelector("a")).size()>10);}
 @Test public void b_personnelEdit()throws Exception{page("/system/user/edit/880002");type(By.id("userName"),"Selenium修改学生");js("submitHandler()");wait.until(x->{try{return FullFunctionalTest.scalar("select count(*) from sys_user where user_id=880002 and user_name='Selenium修改学生'")==1;}catch(Exception e){return false;}});page("/system/user");assertTrue(d.findElement(By.tagName("body")).getText().contains("Selenium修改学生"));}
 @Test public void c_excelImportAndTemplateDownload()throws Exception{page("/system/excelImport");d.findElement(By.id("downloadExcelModel")).click();Thread.sleep(1500);assertTrue(Files.list(out).anyMatch(p->p.toString().endsWith(".xls")));org.apache.poi.ss.usermodel.Workbook book=org.apache.poi.ss.usermodel.WorkbookFactory.create(Files.newInputStream(Paths.get("verification/results/junit/user-import.xlsx")));book.getSheetAt(0).getRow(1).getCell(0).setCellValue("seleniumimport5");book.getSheetAt(0).getRow(1).getCell(1).setCellValue("Selenium导入人员");Path file=out.resolve("selenium-users.xls");try(java.io.OutputStream f=Files.newOutputStream(file)){book.write(f);}book.close();d.findElement(By.id("excelFile")).sendKeys(file.toAbsolutePath().toString());wait.until(x->{try{return FullFunctionalTest.scalar("select count(*) from sys_user where login_name='seleniumimport5'")==1;}catch(Exception e){return false;}});assertTrue(d.findElement(By.tagName("body")).getText().contains("成功"));}
 @Test public void d_gateEntryExit()throws Exception{page("/index");long before=FullFunctionalTest.scalar("select count(*) from gate_in_out");WebElement gate=d.findElement(By.cssSelector("li[onclick^=addGate]:not(.hidden)"));gate.click();Thread.sleep(500);List<WebElement> buttons=d.findElements(By.cssSelector(".layui-layer-btn0"));if(!buttons.isEmpty())buttons.get(0).click();wait.until(x->{try{return FullFunctionalTest.scalar("select count(*) from gate_in_out")>before;}catch(Exception e){return false;}});page("/system/gateInOut/viewMy");assertFalse(d.findElements(By.cssSelector("#bootstrap-table tbody tr")).isEmpty());}
 @Test public void e_attendanceJoinAndSignIn()throws Exception{long id=FullFunctionalTest.scalar("select project_id from project_info where project_name='JUnit考勤' limit 1");page("/system/joinProject");type(By.name("projectId"),""+id);js("submitHandler()");Thread.sleep(2500);page("/system/projectAttend/add");assertTrue(d.findElement(By.tagName("body")).getText().contains("JUnit考勤"));long before=FullFunctionalTest.scalar("select count(*) from project_attend");js("submitHandler()");wait.until(x->{try{return FullFunctionalTest.scalar("select count(*) from project_attend")>before;}catch(Exception e){return false;}});page("/system/projectAttend/my");}
 @Test public void f_libraryBorrowAndReturn()throws Exception{page("/system/bookInfo");assertTrue(d.findElement(By.tagName("body")).getText().contains("JUnit测试图书"));WebElement borrow=d.findElement(By.xpath("//a[contains(.,'借阅')]"));long before=FullFunctionalTest.scalar("select count(*) from book_borrow_record");borrow.click();confirmLayer();wait.until(x->{try{return FullFunctionalTest.scalar("select count(*) from book_borrow_record")>before;}catch(Exception e){return false;}});page("/system/bookBorrowRecord");List<WebElement> returns=d.findElements(By.xpath("//a[contains(.,'还书') or contains(.,'归还')]"));assertFalse(returns.isEmpty());returns.get(0).click();confirmLayer();Thread.sleep(800);page("/system/bookBorrowRecord");}
 @Test public void g_cardWriteCancelIssue()throws Exception{page("/system/user/card/880001");long before=FullFunctionalTest.scalar("select count(*) from campus_card_write where user_id=880001");d.findElement(By.xpath("//button[contains(.,'写卡')]")).click();confirmLayer();wait.until(x->{try{return FullFunctionalTest.scalar("select count(*) from campus_card_write where user_id=880001")>before;}catch(Exception e){return false;}});Thread.sleep(1000);page("/system/user/card/880001");d.findElement(By.xpath("//button[contains(.,'注销')]")).click();confirmLayer();wait.until(x->{try{return FullFunctionalTest.scalar("select count(*) from campus_card where user_id=880001")==0;}catch(Exception e){return false;}});page("/system/user/card/880001");d.findElement(By.xpath("//button[contains(.,'开卡')]")).click();confirmLayer();wait.until(x->{try{return FullFunctionalTest.scalar("select count(*) from campus_card where user_id=880001")==1;}catch(Exception e){return false;}});page("/system/user/card/880001");}
 @Test public void h_walletRechargeAndDebit()throws Exception{page("/campus/wallet/detail/880001");d.findElement(By.xpath("//button[normalize-space()='充值']")).click();type(By.id("amount"),"2.00");d.findElement(By.id("submit")).click();wait.until(ExpectedConditions.alertIsPresent()).accept();wait.until(x->d.findElement(By.id("message")).getText().contains("充值成功"));d.findElement(By.xpath("//button[normalize-space()='划扣']")).click();type(By.id("debitAmount"),"1.00");d.findElement(By.id("debitSubmit")).click();wait.until(ExpectedConditions.alertIsPresent()).accept();wait.until(x->d.findElement(By.id("message")).getText().contains("划扣成功"));assertTrue(d.findElements(By.cssSelector("#rows tr")).size()>=2);}
 @Test public void i_merchantAndFinancePages()throws Exception{page("/campus/merchant");d.findElement(By.xpath("//button[contains(.,'新增商户')]")).click();String name="Selenium商户"+System.currentTimeMillis();type(By.cssSelector("#save [name=name]"),name);Select category=new Select(d.findElement(By.cssSelector("#save [name=category]")));category.selectByIndex(category.getOptions().size()-1);for(String field:new String[]{"owner_name","contact"})type(By.cssSelector("#save [name="+field+"]"),"测试负责人");for(String field:new String[]{"owner_phone","phone"})type(By.cssSelector("#save [name="+field+"]"),"13800000006");type(By.cssSelector("#save [name=address]"),"测试校区");d.findElement(By.cssSelector("#saveButton")).click();wait.until(x->{try{return FullFunctionalTest.scalar("select count(*) from campus_merchant where name='"+name+"'")==1;}catch(Exception e){return false;}});Files.write(out.resolve("i_merchant_created.png"),((TakesScreenshot)d).getScreenshotAs(OutputType.BYTES));page("/campus/finance");long before=FullFunctionalTest.scalar("select count(*) from campus_finance_batch");d.findElement(By.id("internalTab")).click();d.findElement(By.id("runButton")).click();Thread.sleep(300);try{d.switchTo().alert().accept();}catch(NoAlertPresentException ignored){}wait.until(x->{try{return FullFunctionalTest.scalar("select count(*) from campus_finance_batch")>before;}catch(Exception e){return false;}});assertTrue(d.findElement(By.tagName("body")).getText().contains("对账"));}
 @Test public void j_permissionsAndUnauthorizedAccess(){page("/system/permission");assertTrue(d.findElement(By.tagName("body")).getText().contains("角色"));d.manage().deleteAllCookies();d.get(FullFunctionalTest.base+"/login");type(By.name("username"),"teststudent");type(By.name("password"),"Test2026ok");d.findElement(By.id("btnSubmit")).click();wait.until(x->x.getCurrentUrl().contains("/index"));page("/system/permission");assertTrue(d.findElement(By.tagName("body")).getText().contains("权限"));}
}




